from typing import List

class Solution:
    def minMaxSums(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)

        ways = [0] * n
        comb = [0] * k
        comb[0] = 1
        ways[0] = 1

        for m in range(1, n):
            upper = min(m, k - 1)
            for t in range(upper, 0, -1):
                comb[t] = (comb[t] + comb[t - 1]) % MOD
            ways[m] = sum(comb[:upper + 1]) % MOD

        ans = 0
        for i, x in enumerate(nums):
            ans = (ans + x * (ways[i] + ways[n - 1 - i])) % MOD

        return ans
